def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    d = dividers(g)
    side, wall_col = None, None
    for y, c in d["rows"]:
        if c == bg:
            continue
        if y == 0:
            side, wall_col = 'top', c
        elif y == H - 1:
            side, wall_col = 'bottom', c
    for x, c in d["cols"]:
        if c == bg:
            continue
        if x == 0:
            side, wall_col = 'left', c
        elif x == W - 1:
            side, wall_col = 'right', c

    out = g.copy()
    emit(out, "Start from the input: a wall of colour %d on the %s edge and short segments parallel to it." % (wall_col, side))

    objs = [o for o in objects(g, bg) if o["colour"] != wall_col]

    def dist(o):
        y0, x0, y1, x1 = o["box"]
        if side == 'top':
            return y0
        if side == 'bottom':
            return H - 1 - y1
        if side == 'left':
            return x0
        return W - 1 - x1

    objs.sort(key=dist, reverse=True)
    for o in objs:
        y0, x0, y1, x1 = o["box"]
        c = o["colour"]
        if side == 'top':
            out[1:y1 + 1, x0:x1 + 1] = c
        elif side == 'bottom':
            out[y0:H - 1, x0:x1 + 1] = c
        elif side == 'left':
            out[y0:y1 + 1, 1:x1 + 1] = c
        else:
            out[y0:y1 + 1, x0:W - 1] = c
        emit(out, "Sweep the colour %d segment (distance %d from the wall) toward the wall, filling the strip up to the wall; nearer segments overwrite farther ones." % (c, dist(o)))

    emit(out, "All segments swept to the wall; final result.")
    return out
